export const writePreviousReleaseTree = async (tree: PreviousReleaseTree, root: string): Promise<void> => {
  for (const [path, value] of Object.entries(tree.files)) {
    await mkdir(dirname(join(root, path)), { recursive: true })
    await writeFile(join(root, path), `${JSON.stringify(value, null, 2)}\n`)
  }
}
